"""Translates Golem95 (and its OneLOop) into the Java of Sphere's engine.

usage: python -I f2j.py <golem95-source-root> <output-java-dir> <package>
"""
import os
import sys
import traceback

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from fsrc import statements, ParseError  # noqa: E402
from fmodel import Reader  # noqa: E402
from fsem import Program  # noqa: E402
from fgen import Gen, GenError, mod_class, mod_field  # noqa: E402

root, out, package = sys.argv[1], sys.argv[2], sys.argv[3]
# Generated by scripts, replaced in Sphere by algorithms that do what the scripts wrote out.
SKIP = {"tens_comb.f90", "form_factor_higher_ranks.f90"}

files = []
for base, _, names in os.walk(os.path.join(root, "src")):
    for n in sorted(names):
        if n.endswith(".f90") and n not in SKIP:
            files.append(os.path.join(base, n))
files.append(os.path.join(root, "avh_olo-3.6.1", "avh_olo_xkind.f90"))
files.append(os.path.join(root, "avh_olo-3.6.1", "avh_olo.f90"))

modules = []
for f in files:
    modules.extend(Reader(statements(f, os.path.relpath(f, root).replace("\\", "/"))).units())


def higher_ranks_module():
    """form_factor_higher_ranks as a model only: its 1,312 functions, written out by gen_form_factors.py,
    are each F^{N,r}_g = (-1/2)^g (-1)^r I_N^{n+2g}(l1..lk); Sphere computes that one formula in Java."""
    from fmodel import Module, Proc, VarDecl, Interface
    m = Module("form_factor_higher_ranks", 0, "src/higherrank/form_factor_higher_ranks.f90")
    m.synthetic = True
    for n in range(1, 7):
        ranks = range(1, n + 2) if n >= 5 else range(1, n + 11)
        for r in ranks:
            if r <= n:
                continue
            for g in range(0, (r // 2 + 1) if n < 6 else 1):
                name = chr(ord("a") + g) + f"{n}{r}"
                k = r - 2 * g
                specs = []
                for suffix, last, dims in (("_b", "b_pin", None), ("_s", "set", [(None, ":")])):
                    args = [f"l{i}" for i in range(1, k + 1)] + [last]
                    p = Proc(name + suffix, "function", args, name + suffix, set(), None, 0, m.file)
                    for a in args[:-1]:
                        p.decls[a] = VarDecl(a, "integer", None, None, None, set(), "in", None, None, 0)
                    p.decls[last] = VarDecl(last, "integer", None, None, dims, set(), "in", None, None, 0)
                    p.decls[p.result] = VarDecl(p.result, "type", "form_factor", None, None, set(), None, None, None, 0)
                    p.order = list(p.decls)
                    p.synthetic = (g, n, r, suffix)
                    p.module = m
                    m.procs[p.name] = p
                    specs.append(p.name)
                itf = Interface("generic", name, 0)
                itf.procs = specs
                m.interfaces.append(itf)
    m.private = {p for p in m.procs}
    return m


modules.append(higher_ranks_module())
prog = Program(modules)
# modules that only the skipped files used are still translated; uses of the skipped ones are dropped
for m in modules:
    m.uses = [u for u in m.uses if u.module in prog.modules]
    for p in m.procs.values():
        p.uses = [u for u in p.uses if u.module in prog.modules]

gen = Gen(prog, notes=[])
os.makedirs(out, exist_ok=True)
written = 0
# Modules Sphere writes by hand, whose Fortran is read only for the signatures the others call:
# cache_generic keys its table by a 64-bit hash alone and reserves two million entries per engine;
# Sphere's cache is keyed by the whole key, so it can never answer for another integral.
HANDWRITTEN = {"cache_generic"}
for m in modules:
    if getattr(m, "synthetic", False) or m.name in HANDWRITTEN:
        continue                     # written by hand in Sphere
    try:
        src = gen.module_source(m, package)
    except (GenError, KeyError) as e:
        gen.failures.append(f"MODULE {m.name}: {e}")
        traceback.print_exc(limit=2)
        continue
    with open(os.path.join(out, mod_class(m) + ".java"), "w", encoding="utf-8", newline="\n") as fh:
        fh.write(src)
    written += 1

# The engine: one instance of every module, wired together.
L = [f"package {package};", "",
     "/**",
     " * One Golem95 engine: an instance of every module of Golem95 1.3.4 and OneLOop 3.6.1, translated.",
     " * Each holds what its Fortran module keeps between calls, so engines are independent of one another:",
     " * one per thread computes in parallel, which the Fortran library, with its module variables, cannot.",
     " * Generated by Sphere's Fortran translator; do not edit.",
     " */",
     "public final class GolemCore {", "",
     "    /** Where the library's own messages go (its units 0, 6 and 12). */",
     "    public final FIO io = new FIO();", ""]
for m in modules:
    L.append(f"    public final {mod_class(m)} {mod_field(m)} = new {mod_class(m)}(this);")
L += ["}", ""]
with open(os.path.join(out, "GolemCore.java"), "w", encoding="utf-8", newline="\n") as fh:
    fh.write("\n".join(L))

# Functional interfaces for the procedures passed as arguments.
for name, (params, rt) in sorted(gen.funcs.items()):
    src = [f"package {package};", "", f"/** A procedure argument of Golem95: {', '.join(params)} -> {rt}. */",
           "@FunctionalInterface", f"public interface {name} {{",
           f"    {rt} call({', '.join(f'{p} a{i}' for i, p in enumerate(params))});", "}", ""]
    with open(os.path.join(out, name + ".java"), "w", encoding="utf-8", newline="\n") as fh:
        fh.write("\n".join(src))

print(f"{written} modules written, {len(gen.failures)} procedures not translated")
for f in gen.failures:
    print("  " + f)
